import random
from math import gcd
from itertools import combinations

def xor_of_coprimes(n, x):
    """Calculate the bitwise XOR of all numbers y in A and y coprime with x."""
    result = 0
    for i in range(1, n + 1):
        if gcd(i, x) == 1:
            result ^= i
    return result

c, n = map(int, input().split())
ai = set()

while len(ai) != n:
    a = random.randint(1, c)
    ai.add(a)

assert len(ai) == n

class Solution:
    def __init__(self, c, n):
        self.c = c
        self.n = n

    def run(self):
        q = 0.65 * self.c
        q = int(q)
        q = min(q, len(ai))  # The maximum number of queries allowed
        q = max(1, q)  # At least one query

        queries = set()
        answers = {}

        def ask(x):
            nonlocal queries, answers
            xor = xor_of_coprimes(len(ai), x)
            answers[x] = xor
            return xor

        def next_query():
            nonlocal ai, queries, answers
            for a in ai:
                xor = ask(a)
                if xor not in answers:
                    queries.add(xor)
                    break

        while q > 0:
            next_query()
            q -= min(1, q)

        for i in range(1, c + 1):
            if i not in queries:
                ai.add(i)

        # The set A' we are trying to guess
        return sorted(set(ai))

# Solving the problem by following the interactions
print(len(ai), *sorted(ai))
for _ in range(len(ai)):
    ask(*map(int, input().split()))
    assert ask(0) == xor_of_coprimes(len(ai), 1)  # Checking the initial xor sum with A={x, x}
