def find_xor_accumulator(c, n):
    # Initialize variables
    xor = 0
    odd_xor = 0
    found_pairs = [False] * n
    accumulator = [False] * (2 ** n)
    seen = set()
    candidate_n_primes = pow(2, n - 1) // 2

    # Generate all possible sets
    for index in range(1, c + 1):
        xor ^= index
        odd_xor ^= index
        accumulator[xor] = True
        accumulator[odd_xor] = True
        seen.add(xor)
        seen.add(odd_xor)

        # Find n distinct numbers that are coprime with 'index'
        odd_ind_pair = {}
        for pair in seen:
            for prime in range(2, n + 1):
                if pair & (1 << (prime - 1)):  # Check if prime is a prime factor
                    if gcd(index, prime) == 1:
                        odd_ind_pair[prime] = True
                        break

        # Check for all possible n prime factors
        if len(odd_ind_pair) >= n and pair_found_index(prime - 1):
            if n == number_of_pairs_in_accumulator(found_pairs, n):
                return xor
            for key in odd_ind_pair:
                accumulator[1 << key] = True

def pair_found_index(k):
    for i in range(k):
        if len(found_pairs[i]) == n:
            return True
    return False

def number_of_pairs_in_accumulator(found_pairs, n):
    pair_list = []
    for elem in range(1 << n):
        current = elem
        for index, pair in enumerate(found_pairs):
            if current & (1 << (index - 1) and pair):
                current ^= pair
        pair_list.append(current)
    return len(list(OrderedDict.fromkeys(pair_list)))

