# Function to check if the arrangement is beautiful
def is_beautiful(points):
    n = len(points)
    abscissa_pos = defaultdict(int)

    for i in range(n):
        if points[i] == '?':
            abscissa_pos[i] = n
        else:
            abscissa_pos[i] = abscissa_pos[ord(points[i]) - ord('a')] + 1

    pairs = [p for _, p in abscissa_pos.items()]
    connections = defaultdict(lambda: defaultdict(list))

    def get_index(v):
        if abs(v - pairs[0]) > abs(v - pairs[1]):
            return pairs[0], pairs[1]
        return pairs[1], pairs[0]

    for i in range(1, n):
        p1, p2 = get_index(i)
        index1, index2 = abscissa_pos[p1], abscissa_pos[p2]
        x3 = (index1 + index2) // 2
        y3 = -(index1 + index2) // 2 + x3
        d = sqrt(pow(x3 - p1, 2) + pow(y3 - p1, 2))
        sqrt_val = int(d)
        while sqrt_val > 0:
            if d == ((index1 + index2) // 2 + sqrt_val):
                connections[p1][index1 + sqrt_val].append((p2, x3 + sqrt_val))
            if d == ((index1 + index2) // 2 - sqrt_val):
                connections[p1][index1 - sqrt_val].append((p2, x3 - sqrt_val))

            sqrt_val -= 1

    if n % 2 == 1:
        return ceil(sqrt(n)) + int(n > 5)
    else:
        return 2 * ceil(sqrt(len(pairs))) - 2



