def count_ways(n, marked_points):
    marked_positions = [(i, ord(char) - ord('a')) for i, char in enumerate(marked_points) if char != '?']
    valid_couples = 0
    for upstream_fix in range(26):
        for downstream_fix in range(26):
            upstream_index, _ = [i for i, (upstream_fix_pos, _) in enumerate(marked_positions) if upstream_fix_pos == upstream_fix]
            downstream_index, _ = [i for i, (_, downstream_fix_pos) in enumerate(marked_positions) if downstream_fix_pos == downstream_fix]
            if upstream_index < downstream_index:
                min_upper, max_lower = min(upstream_fix_pos, downstream_fix_pos), max(upstream_fix_pos, downstream_fix_pos)
                valid_couples += connections[max_lower - min_upper + 1]

    return valid_couples % 4294967296



