from typing import List

def calculate_uniform_teams(soldiers: List[int], officers: List[int]) -> int:
    n_soldiers = len(soldiers)
    n_officers = len(officers)
    dp_sold = [1] * (n_soldiers + 1)
    dp_off = [1] * (n_officers + 1)

    for skill in soldiers:
        for i in range(n_soldiers, -1, -1):
            if i - skill >= 0:
                dp_sold[i] += dp_sold[i - skill]
                dp_sold[i] %= 1000000007

    for skill in officers:
        for i in range(n_officers - 1, -1, -1):
            if i + skill < n_officers:
                dp_off[i + 1] += dp_off[i]
                dp_off[i + 1] %= 1000000007

    return sum(dp_sold[n_soldiers]) * sum(dp_off[1]) % 1000000007

def process_changes(changes: List[List[int]], soldiers: List[int]) -> List[int]:
    _, t, x = changes.pop(0)
    if t == 1:
        soldiers[x - 1] = 0
    else:
        soldiers[x - 1] = 1

    result = []
    for change in changes:
        _, t, x = change
        if t == 1:
            result.append(calculate_uniform_teams(soldiers, officers))
        else:
            _, x = change
            result.append(calculate_uniform_teams(soldiers, sorted(soldiers, reverse=True)))

    return result

