    first_half_samples = set()
    first_half_non_reachable = set()
    second_half_samples = set()

    parents = defaultdict(lambda: -sys.maxsize)
    min_overall_ms_needed = -sys.maxsize

    for node in range(n):
        if in_degree[node] == 1:
            parents[node] = 0
            first_half_samples.add(node)
            first_half_non_reachable.add(node)

    for i in range(k):
        for first_half_sample in first_half_samples:
            for neighbor in range(n):
                if (neighbor, first_half_sample) not in edges:
                    break
            else:
                parents[neighbor] = max(parents[neighbor], ai[neighbor] + parents[first_half_sample])
                min_overall_ms_needed = max(min_overall_ms_needed, parents[neighbor])
                first_half_samples.add(neighbor)
                first_half_non_reachable.add(neighbor)
                break

    for sample in first_half_samples:
        for other in range(n):
            if other not in parents and other not in first_half_samples:
                parents[other] = max(parents[other], ai[other])
                min_overall_ms_needed = max(min_overall_ms_needed, parents[other])
                break

    for node in range(n):
        row = 1 if in_degree[node] <= k else 2
        for neighbor in range(node + 1, len(in_degree)):
            if (neighbor, node) in edges:
                value = ai[neighbor]
                if row == 1 and (deg := in_degree[node]) <= k:
                    enough_1 = value + parents[node]
                    enough_2 = min_overall_ms_needed + parents[neighbor]
                    if (enough_1 == enough_2):
                        parents[neighbor] = max(enough_1, enough_2)
                    elif (enough_1 < enough_2):
                        parents[neighbor] = value
                    row += 1
                elif row == 2 and (deg >= k and all(a >= k and b >= k and a + b >= k for a, b in edges[node])):
                    parents[neighbor] = max((parents[node] + value) % (10 ** 9 + 7), parents[neighbor])
                    row += 1
                elif row == 2 and hard_case(node, neighbor, edges, in_degree):
                    max_value = ai[node] + ai[neighbor]
                    parents[neighbor] = max(parents[neighbor], max_value)
                    continue
                else:
                    parents[neighbor] = max(parents[neighbor], parent_score(node, neighbor, edges))
                    row += 1

    return min_overall_ms_needed

def hard_case(node, neighbor, edges, in_degree):
    deg_first = max(in_degree[node], in_degree[neighbor])
    deg_second = deg_first + 1
    l = [node, neighbor]
    l.extend(set(s) - set(l) for s in edges)
    return not all(neighbor in s for s in l) and (deg_first + 1 > min(deg_first, deg_second) and deg_second < k or deg_first > k)

def parent_score(node, neighbor, edges):
    cur_ans = 0
    for node1, node2 in edges:
        if node1 == node:
            if node2 == neighbor:
                pass
            elif node2 in edges[node1][::-1]:
                cur_ans += ai[node2] + cur_ans
            elif node2 in edges[node2][::-1]:
                cur_ans += ai[node1] + cur_ans
    return cur_ans % (10 ** 9 + 7)

