from math import comb

def factorize(n):
    i = 2
    factors = []
    while n > 1:
        if n % i == 0:
            factors.append(i)
            n //= i
        else:
            i += 1
    return factors

def dfs(items, used, current):
    if len(current) == 1:
        return 1 if not any(used[k] for k in current) else 0
    ans = comb(len(items) - len(current) + 1, 2)
    for i in range(len(current) - 1):
        j = i + 1
        while j < len(current):
            if all(used[k] for k in range(i, j + 1)) and all(not used[k] for k in range(j + 1, len(current))):
                ans = (ans * dfs(items, used, current[:i] + items[0] + current[j + 1:])) % 1000000007
            j += 1
    return ans

def num_optimal_profiles(n):
    factors = factorize(n)
    if n >= 2:
        if len(factors) == 1:
            return 1 if factors[0] > 2 else (factors[0] - 1) * (1 + pow(factors[0], n - 1, 1000000007)) % 1000000007
        if len(factors) == 2:
            return pow(2, n - 1, 1000000007)
    return dfs(list(range(1, n + 1)), {i:n for i in range(1, n + 1)}, list(range(1, n + 1)))

