from collections import defaultdict

def findMinDestroySteps(N, edges):
    destroy_graph, adjacency_list = {}, defaultdict(list)

    # Create adjacency list representation
    for src, dest in edges:
        adjacency_list[src].append(dest)
        if dest in destroy_graph:
            destroy_graph[src].add(tuple(destroy_graph[dest]))
        else:
            destroy_graph[src] = {tuple(destroy_graph[src]), tuple(destroy_graph[dest])}

    destroy_steps = 0
    visited = set()

    def dfs(node):
        nonlocal destroy_steps
        visited.add(node)
        if node in destroy_graph and type(destroy_graph[node]) == set:
            destroy_steps += 1
        for neighbor in adjacency_list[node]:
            if neighbor not in visited:
                destroy_steps = dfs(neighbor)

    for i in range(1, N+1):
        if i not in visited:
            dfs(i)

    return destroy_steps + 1  # Add one extra step for the last vertex

def main():
    N, M = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(M)]

    min_steps = findMinDestroySteps(N, edges)

    print(min_steps)
    for _ in range(min_steps):
        step, vertices = input().split()
        vertices = list(map(int, vertices.split()))
        print(int(step), *vertices)

if __name__ == "__main__":
    main()
