def find_critical_vertices(N, M, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    critical_vertices = []
    in_degree = {i: 0 for i in range(1, N+1)}

    for u, vs in graph.items():
        for v in vs:
            in_degree[v] += 1

    for u, deg in in_degree.items():
        if deg == 0:
            critical_vertices.append(u)

    for i in range(1, len(critical_vertices)):
        critical_vertices[i] = sorted(critical_vertices[i-1], key=lambda x: critical_vertices.index(x))

    return critical_vertices

def find_in_destructive_cycles(N, M, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    critical_vertices = find_critical_vertices(N, M, edges)
    result = []

    while critical_vertices:
        critical_v = critical_vertices.pop(0)
        for adjacent in graph[critical_v]:
            if adjacent in edges and adjacent in graph and adjacent not in edges:
                critical_vertices.append(adjacent)

        result.append(critical_vertices)

    return result

def destroy_graph(N, M, edges):
    destroy_steps = 0
    while edges:
        if len(edges) <= 3:  # Simple case: destroy two adjacent vertices or one vertex with no possible step
            steps = M if edges else 0
            break

        step_result = find_in_destructive_cycles(N, 1 + 2 + M, edges)
        for kill_at_once in step_result:
            edges -= {kill_at_once}
            destroy_steps += 2
        else:
            destroy_steps += 1
    return destroy_steps

