from collections import defaultdict

def min_steps_to_destroy_graph(N, M, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v] = [u]  # Set the edge direction to undirected

    max_level = 0
    # Find the maximum level
    for i in range(1, N+1):
        max_level = max(max_level, len(graph[i]))

    dp = [[0] * (max_level + 1) for _ in range(3)]
    directions = [[0, 1], [1, 0]]  # Directions for DFS: horizontal (1,0), vertical (0,1)

    def dfs(node, level):
        dp[len(graph[node])][level] = 1  # Mark edge level as visited
        stack = [[node, level]]  # Stack for DFS
        while stack:
            cur_node, current_level = stack.pop()
            for neighbor in graph[cur_node]:
                if dp[len(graph[cur_node])][current_level]:
                    continue  # Skip edges already considered during this order
                if current_level >= len(graph[neighbor]):  # Avoid revisiting paths
                    continue
                if dp[current_level + 1][len(graph[neighbor])] == 0:
                    # New path, update maximum level needs
                    dp[len(graph[neighbor])][current_level + 1] = 1
                    stack.append([neighbor, current_level + 1])
                else:
                    break  # Maintain towerance over same edge levels

    # Factor out edge levels between current towerance height and maxlevel
    remaining_levels = [(left_level, max_level) for left_level in range(max_level)]
    for node, level in graph.items():
        for next_level in level:
            remaining_levels[next_level-1] = min(remaining_levels[next_level-1], (level[0]+1, max_level))

    total_edges = 0
    ans = []
    for i in range(len(remaining_levels)):
        max_lvl, final_lvl = remaining_levels[i]
        if dp[max_lvl][final_lvl] == 0:
            # If stack is not empty after DFS graph fill, increment total edges for current level
            while dp[max_lvl][final_lvl] == 0:
                stack = []
                total_edges += 2  # Add current game number of steps, as well as previous step of number of games
                level = (max_lvl + 1) % (max_level + 1)
                path = [(i+1, level-1)]
                tmp_empty = [[0 for _ in range(N+1)] for _ in range(3)]
                while stack:
                    node, level = stack.pop()
                    for adj_node in graph[node]:
                        if dp[len(graph[adj_node])][level] == 0 or tmp_empty[level][adj_node-1] >= final_lvl:
                            tmp_empty[level][adj_node-1] = final_lvl
                            stack.append([adj_node, level])
                        else:
                            path.append((node+1, (node+2)%2))
                ans.extend(path)

    return total_edges
