class Solution:
    def calculate_team_efficiency(self, n: int, skills: list[int], changes: int) -> list[int]:
        n_skills = {}
        for skill in skills:
            n_skills[skill] = n_skills.get(skill, 0) + 1

        max_skill = max(n_skills)
        min_skill = min(n_skills)
        dp, siz = [0] * (max_skill + 4), [ (2 ** (max_skill + 1) // 3, 2 ** (max_skill * 3 // 2)) ]

        for i in range(min_skill, 1, -1):
            dd = {}
            for skill in n_skills:
                if skills[n_skills[skill] - 1] >= i:
                    continue
                if i > skill:
                    continue

                if i not in dd:
                    dd[i] = [ (0, 0), (0, 0) ]
                dd[i][skills[skill] - 1 + 1] = dd[i].pop()

            for j in n_skills:
                count_skill, tiles = dd.get(j, (0, 0))

                dp[j - 1] = (dp[j - 1] + count_skill) % MOD

                if j - 1:
                    dp[j - 2] = (dp[j - 2] + tiles[1] - 2 ** ((j - 2) // 4)) % MOD

                if j * 2:
