        return [pow(2, i - 1, MOD) for i in range(1, siz[0])] + \
            [ (2 ** (siz[1][1] // 4) - pow(siz[1][0], 3, MOD) + MOD) % MOD if siz[1][0] > 1 else 0 ] 

