from itertools import permutations
from math import inf

class ManhattanCycle:
    def __init__(self, cities):
        self.cities = cities
        self.coordinates = []
        for city in self.cities:
            self.coordinates.append((city[0], city[1]))

    def calculate_distance(self, city1, city2):
        x1, y1 = self.coordinates[city1][0], self.coordinates[city1][1]
        x2, y2 = self.coordinates[city2][0], self.coordinates[city2][1]
        return abs(x1 - x2) + abs(y1 - y2)

    def calculate_hamiltonian_cycle_length(self):
        cycles = permutations(range(len(self.cities)))
        max_length = 0

        for cycle in cycles:
            current_route = 0
            for i in range(len(cycle)):
                next_city = cycle[(i + 1) % len(cycle)]
                current_route += self.calculate_distance(i, next_city)
            max_length = max(max_length, current_route)

        return max_length

def read_input():
    n = int(input())
    cities = []
    for _ in range(n):
        x, y = map(int, input().split())
        cities.append((x, y))
    return ManhattanCycle(cities)

