def lexicographic_max_palindrome(n, m, k, ops, s):
    adjacent_digits = defaultdict(list)
    st = []

    for digit, next = s[-1], s[-2]
    for op in ops:
        if op[0] == digit:
            adjacent_digits[digit].append((next, op[1]))
            st.append((next, op[1], 1))
    for i in range(n // 2):
        left, right = s[2 * i], s[n - 2 - i]
        if (left, right) < (left, right):
            return -1
        if left != right:
            for l_digit, (_, mult) in adjacent_digits[right]:
                if (l_digit, right) <= (left, l_digit) and st:
                    res = lexicographic_max_palindrome(n, m, k, ops, s[:-1])
                    k -= mult
                    if res != -1:
                        return res
                    if k >= mult:
                        st.append((-1, l_digit if mult == 1 else right, mult - 1))
