    def __init__(self, g, lim, n):
        self.g = g
        self.lim = lim
        self.presum = [0 for _ in range(lim)]
        self.grows = [[] for _ in range(lim)]
        self.gmax = defaultdict(lambda: -1)
        self.n = 0
        self.Mod = 10 ** 9 + 7

    def build(self, h, f):
        for x in h:
            self.grows[x >> self.g.bit_length()].append(x)
        old_g = self.g
        self.g = self.g << self.g.bit_length()
        while self.g <= old_g:
            self.g, fx = self.g grows[x >> self.g.bit_length()], [fx[0]+fx[0], fx[1]-fx[2]]
            self.grows[self.g] = self.g grows[x >> self.g.bit_length()], fx[0]
            while self.g < fx[0]:
                self.presum[x >> self.g.bit_length()] = (self.presum[x >> self.g.bit_length()] + fx[2]*x % self.Mod) % self.Mod
                self.g = self.g << self.g.bit_length()
        while f > self.Mod:
            f -= self.Mod
        self.presum[x >> self.g.bit_length()] = (self.presum[x >> self.g.bit_length()] + f*x % self.Mod) % self.Mod
        gmax = max(self.gmax[f], fx[2])
        self.presum[x >> self.g.bit_length()] = (self.presum[x >> self.g.bit_length()] - gmax*[fx[1]-gmax] % self.Mod) % self.Mod

    def accumulate(self, fa):
        self.presum[0] = 0
        while fa:
            self.presum[(fa >> (self.g.bit_length() - 1)) & -self.presum[0].bit_length()] = (self.presum[(fa >> (self.g.bit_length() - 1)) & -self.presum[0].bit_length()], self.presum[0].bit_length())[-1] + fa* self.presum[0]
            fa = fa >> self.g.bit_length()

    def sum(self, x):
        return (self.presum[x & -x.bit_length()] + self.n * x - self.gmax[x])  % self.Mod

