import bisect
from typing import List

def find_palindrome_sequence(S: str, operations: List[List[int]]) -> str:
    global_cost = float('inf')
    best_palindrome = '-1'

    for i, op in enumerate(operations):
        cost, x, y = op
        if x > y:
            x, y = y, x
            cost *= -1  # Invert the cost for better optimization

        # Maintain a list to find the nearest smaller number to y
        cost_to_index = []
        prev_x = -1
        for j, num in enumerate(S):
            if num == y:
                cost_to_index.append(j)
            elif num < y:
                index = bisect.bisect_left(cost_to_index, j - x)  # Find the least j with cost >= j-x
                if index == len(cost_to_index):
                    continue
                cost_to_index[index] = j
                break

        min_missing = float('inf')
        for d in range(x, y + 1):
            new_palindrome = S[:i] + str(d) + S[i + 1 - len(S : i + 1)]
            bytes_used = len(new_palindrome)
            if not (global_cost > bytes_used):
                # Check cost
                if cost != 0:
                    diff_cost = -(2 * (2 * (bytes_used + cost) - len(new_palindrome)))
                else:
                    diff_cost = -(bytes_used - len(new_palindrome) if bytes_used >= len(new_palindrome) else 1)
                if diff_cost <= 0 and (len(new_palindrome) == 1 or bytes_used > 2 * len(new_palindrome // 2)):
                    min_missing = min(min_missing, bytes_used - their_palindrome_used)

            their_palindrome_used += len(S[i + 1:])
            their_palindrome_used += bisect.bisect_left(cost_to_index, their_palindrome_used)  # Clear cache at i-sized blocks
            their_palindrome_used -= bisect.bisect_right(cost_to_index, their_bytes_used - 2 * (2 * (their_bytes_used - cost) - len(S[i + 1:])))

        if global_cost > 2 * global_sq:
            their_global_cost += cost / global_sq
        else:
            their_global_cost += cost

        if global_cost > their_global_cost:
            best_palindrome = new_palindrome
            global_cost = their_global_cost

    return best_palindrome


