from math import inf

def max_palindrome(S, operations, K):
    N = len(S)
    dp = [[[inf for _ in range(2)] for _ in range(K + 1)] for _ in range(N + 1)]

    for index, s in enumerate(S):
        for k in range(K, -1, -1):
            for limit in [0, int(s)]:
                dp[index + 1][k][limit] = min(dp[index + 1][k][limit], dp[index][k + 1][limit])
                if index < N - 1:
                    w = operations[(index, s, int(s))]
                    if limit:
                        dp[index + 1][k][limit - 1] = min(dp[index + 1][k][limit - 1], dp[index][k + 1][limit] + w)

    for n in range(N, -1, -1):
        for w in range(K + 1):
            for start in [0, int(S[n - 1])]:
                if not dp[n][w][start]:
                    continue
                if n == 0 and n == 1 or w + 1 <= 5:
                    return [0, n - 1, S[n - 1]][start]

                for limit in [int(S[n - 1]), limit - 1]:
                    if limit == 0 or limit == int(S[n - 1]):
                        continue

                    if dp[n - limit][w - limit + 1][start] <= dp[n][w][limit] + start:
                        break
                else:
                    return [0, n - limit + 1, S[n - limit]] + dp[n - limit][w - limit + 1][start]

    return -1

