def find_assignment_count(n, assignments):
    # Initialize dp array
    dp = [1] * (n + 1)

    # Iterate over each person
    for i in range(1, n + 1):
        # For each assignment, initialize the current count
        current_count = [0] * (n + 1)
        for j in range(i):
            # Update dp[j] if the current person is happier
            if dp[j] < assignments[j]:
                for k in range(i, 0, -1):
                    if assignments[k] >= assignments[j]:
                        current_count[k - 1] += dp[j] * dp[-k + 1] % 1000000007
                        dp[k - 1] += dp[j] * dp[-k + 1] % 1000000007

                # Reset dp[j] for the current person
                dp[j] = assignments[j]
            else:
                # Update current_count[j + 1] if the current person doesn't care
                current_count[j + 1] += dp[j] * dp[-j] % 1000000007

        # Update dp[i] with the sum of current_count[j] for all j
        for k in range(i, 0, -1):
            dp[i] += dp[k] * dp[-k] % 1000000007

        # Reset previous conditions
        for k in range(i + 1, 0, -1):
            for j in range(i, 0, -1):
                if current_count[j] >= dp[k] * dp[-k + 1] % 1000000007:
                    dp[k] = current_count[j]

    return sum(dp) % 1000000007

print(find_assignment_count(n, assignments))
