import sys

def calculate_elevator_direction_changes(N, M, B):
    if 2 * N > M:
        return -1

    changes = 0
    floors_above = 0
    floors_below = 0

    for i in range(N):
        if B[i] > M or B[i] < -1:
            return -1
        elif B[i] > floors_above:
            changes += floors_below
        elif B[i] > floors_below:
            changes += floors_above
        else:
            changes += 1

        if B[i] > M:
            floors_above += 1
        elif B[i] < -1:
            floors_below += 1

    return changes

